线程池饥饿（ThreadPool Starvation）是 .NET 服务端应用最常见的性能问题，表现为：CPU 不高（可能只有 20-30%）、但请求延迟持续飙升、线程池队列长度 > 0 且持续增长。

**根因**：在 async 方法中同步阻塞（`.Result`、`.Wait()`、`GetAwaiter().GetResult()`），导致线程池线程被占住不释放。.NET 线程池用 hill-climbing 算法动态调线程数，但补线程速度默认约每秒 1-2 个，远跟不上请求到达速率。

**典型场景**：
```csharp
// 罪魁祸首：async 代码同步阻塞
public IActionResult GetData()
{
    var result = _httpClient.GetStringAsync(url).Result; // 阻塞线程池线程
    return Ok(result);
}

// 正确做法
public async Task<IActionResult> GetData()
{
    var result = await _httpClient.GetStringAsync(url); // 释放线程
    return Ok(result);
}
```

**为什么 CPU 不高但延迟高**：线程池线程全在 `.Result` 上阻塞等待 IO 完成，CPU 实际在空转。新请求排在 ThreadPool Queue 里等线程释放，队列越积越长，延迟越来越高。

**定位步骤**：
1. dotnet-counters 看 `threadpool-queue-length` 持续 > 0，`threadpool-thread-count` 缓慢增长
2. dotnet-dump 抓 dump → `threads` 命令看线程栈 → 大量线程停在 `Monitor.Wait` 或 `.Result` 上
3. 顺着栈帧找到同步阻塞的代码行，改成 async/await

**.NET 线程池与 Java 线程池的区别**：.NET 线程池没有你主动设的 corePoolSize/maximumPoolSize（.NET 用 hill-climbing 自适应），也不能自定义队列和拒绝策略。饥饿的表现是排队而非拒绝——请求一直等，不会被快速失败。这其实是更危险的故障模式。

.NET 5+ 引入 `System.Diagnostics.Metrics` API，取代旧的 `EventCounter`。它通过 `Meter` + 具体指标类型暴露业务指标，可以用 dotnet-counters 或 OpenTelemetry 采集。

四种指标类型：
- **Counter\<T\>**：单调递增值，如请求总数、错误总数。只增不减
- **UpDownCounter\<T\>**：可增可减，如活跃连接数、队列长度
- **Histogram\<T\>**：记录值的分布，如请求延迟（会被自动计算 P50/P90/P99）
- **ObservableCounter / ObservableGauge**：回调式，每次采集时调用，适合瞬时值如 CPU 使用率、队列长度

使用方式：
```csharp
private static readonly Meter Meter = new("MyApp", "1.0");
private static readonly Counter<long> Requests = Meter.CreateCounter<long>("http.requests");
private static readonly Histogram<double> Duration = Meter.CreateHistogram<double>("http.duration", "ms");

// 带 Tag 记录
Requests.Add(1, new KeyValuePair<string,object>("method", "GET"));
Duration.Record(42.5, new KeyValuePair<string,object>("path", "/api/users"));
```

配合 OpenTelemetry SDK，这些指标可以导出到 Prometheus、Grafana、Azure Monitor 等后端。`AddMeter("MyApp")` 就是把自定义 Meter 注册到 OTel 采集管道。

using System;
using System.Diagnostics;
using System.Diagnostics.Metrics;
using System.Threading.Tasks;
using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Running;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using OpenTelemetry.Metrics;

// ========== 1. BenchmarkDotNet 微基准测试 ==========
[MemoryDiagnoser] // 必须加，否则看不到分配量
[SimpleJob(RuntimeMoniker.Net80)]
public class StringBenchmarks
{
    private const int N = 1000;

    [Benchmark]
    public string Concat()
    {
        var result = "";
        for (int i = 0; i < N; i++)
            result += i.ToString();
        return result;
    }

    [Benchmark]
    public string Builder()
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < N; i++)
            sb.Append(i);
        return sb.ToString();
    }

    [Benchmark(Baseline = true)]
    public string Create()
    {
        return string.Create(N * 4, 0, (span, _) =>
        {
            for (int i = 0; i < N; i++)
            {
                i.TryFormat(span, out var written);
                span = span.Slice(written);
            }
        });
    }
}

// ========== 2. 自定义业务计数器 ==========
public class AppMetrics
{
    private static readonly Meter Meter = new("MyApp", "1.0");
    private static readonly Counter<long> Requests =
        Meter.CreateCounter<long>("http.requests.total");
    private static readonly Histogram<double> Duration =
        Meter.CreateHistogram<double>("http.requests.duration", "ms");
    private static readonly UpDownCounter<long> Active =
        Meter.CreateUpDownCounter<long>("http.requests.active");
    private static readonly Counter<long> Errors =
        Meter.CreateCounter<long>("http.errors.total");

    public void Record(string path, double ms, int status)
    {
        var tags = new TagList
        {
            { "path", path },
            { "status", status.ToString() }
        };
        Requests.Add(1, tags);
        Duration.Record(ms, tags);
        if (status >= 500) Errors.Add(1, tags);
    }
    public void Started() => Active.Add(1);
    public void Completed() => Active.Add(-1);
}

// ========== 3. 性能中间件 ==========
public class PerfMiddleware
{
    private readonly RequestDelegate _next;
    private readonly AppMetrics _metrics;

    public PerfMiddleware(RequestDelegate next, AppMetrics metrics)
    {
        _next = next;
        _metrics = metrics;
    }

    public async Task InvokeAsync(HttpContext ctx)
    {
        var sw = Stopwatch.StartNew();
        _metrics.Started();
        try
        {
            await _next(ctx);
        }
        finally
        {
            sw.Stop();
            _metrics.Completed();
            _metrics.Record(ctx.Request.Path, sw.Elapsed.TotalMilliseconds, ctx.Response.StatusCode);
        }
    }
}

// ========== 4. 注册 ==========
public static class Di
{
    public static IServiceCollection AddPerf(this IServiceCollection s)
    {
        s.AddSingleton<AppMetrics>();
        s.AddOpenTelemetry().WithMetrics(b => b
            .AddMeter("MyApp")
            .AddAspNetCoreInstrumentation()
            .AddPrometheusExporter());
        return s;
    }
}

// 运行 Benchmark: dotnet run -c Release -- --filter "*StringBenchmarks*"
